Ltac solve_saves :=
  let f := fresh "f" in let R := fresh "R" in let m := fresh "m" in
  let Hfn := fresh "Hfn" in let Hsp := fresh "Hsp" in let Hstk := fresh "Hstk" in let Hrw := fresh "Hrw" in
  intros f R m Hfn Hsp Hstk Hrw;
  let fnv := match type of Hfn with fr_fn _ = ?fn => fn end in
  let r := eval vm_compute in (ffind fnv) in
  let b := match type of Hrw with Step.rw_cells _ _ ?b _ => b end in
  match r with Some (?N, ?cnt) =>
    apply (saves_intro f R m N cnt b); [rewrite Hfn; vm_compute; reflexivity | cbn; lia | lia | exact Hstk | exact Hrw]
  end.

Ltac solve_agrees :=
  let f := fresh "f" in let R := fresh "R" in let Hfn := fresh "Hfn" in
  intros f R Hfn; intros;
  let fnv := match type of Hfn with fr_fn _ = ?fn => fn end in
  let c := eval vm_compute in (cntF fnv) in
  unfold agreesF; rewrite Hfn; change (cntF fnv) with c;
  let k := fresh "k" in let Hk := fresh "Hk" in
  intros k Hk;
  do 12 (destruct k as [|k]; [cbn [liveR nth]; first [reflexivity | assumption | symmetry; assumption | lia] |]); lia.

Ltac solve_tab :=
  cbn [eh_fsize eh_saves_ok eh_agrees_unsaved eh_unsaved_now eh_site_ok eh_pad eh_resume_site EHK];
  repeat match goal with
  | |- _ /\ _ => split
  | |- fsizeF _ = _ => vm_compute; reflexivity
  | |- site_okF _ _ = _ => vm_compute; reflexivity
  | |- padF _ _ = _ => vm_compute; reflexivity
  | |- rsiteF _ _ = _ => vm_compute; reflexivity
  | |- forall f R m, _ => solve_saves
  | |- forall f R, _ => solve_agrees
  end.

